  public static Tacplus.LanguageDependencies.Builder mergeLanguageDependencies(
      Tacplus.LanguageDependencies dst, Tacplus.LanguageDependencies src) {
    Tacplus.LanguageDependencies.Builder builder = dst.toBuilder();
    if (dst.getDependenciesMap().isEmpty()) {
      builder.putAllDependencies(src.getDependenciesMap());
    }
    return builder;
  }

  public static Tacplus.DependenciesRegistry.Builder mergeDependenciesRegistry(
      Tacplus.DependenciesRegistry dst, Tacplus.DependenciesRegistry src) {
    Tacplus.DependenciesRegistry.Builder builder = dst.toBuilder();
    if (dst.getGitlabProjectId().isEmpty()) {
      builder.setGitlabProjectId(src.getGitlabProjectId());
    }
    if (dst.getInterfacesMap().isEmpty()) {
      builder.putAllInterfaces(src.getInterfacesMap());
    }
    if (dst.getImportsMap().isEmpty()) {
      builder.putAllImports(src.getImportsMap());
    }
    return builder;
  }

  public static Tacplus.DependenciesConfig.Builder mergeDependenciesConfig(
      Tacplus.DependenciesConfig dst, Tacplus.DependenciesConfig src) {
    Tacplus.DependenciesConfig.Builder builder = dst.toBuilder();
    if (!dst.hasRegistry() && src.hasRegistry()) {
      builder.setRegistry(src.getRegistry());
    } else if (dst.hasRegistry() && src.hasRegistry()) {
      builder.setRegistry(mergeDependenciesRegistry(dst.getRegistry(), src.getRegistry()).build());
    }
    if (dst.getToolsMap().isEmpty()) {
      builder.putAllTools(src.getToolsMap());
    }
    if (dst.getLangMap().isEmpty()) {
      builder.putAllLang(src.getLangMap());
    } else {
      for (String mk : src.getLangMap().keySet()) {
        if (dst.getLangMap().containsKey(mk)) {
          builder.putLang(
              mk,
              mergeLanguageDependencies(dst.getLangMap().get(mk), src.getLangMap().get(mk))
                  .build());
        } else {
          builder.putLang(mk, src.getLangMap().get(mk));
        }
      }
    }
    return builder;
  }

